from __future__ import annotations

import json
import subprocess
import tempfile
from pathlib import Path
from typing import Iterable, Sequence


class OutlookMailError(RuntimeError):
    """Raised when the Outlook/PowerShell mail module fails."""


def _normalize_addresses(value: str | Sequence[str] | None) -> list[str]:
    if value is None:
        return []

    if isinstance(value, str):
        # Allow either one address or "a@x.com;b@y.com".
        return [part.strip() for part in value.split(";") if part.strip()]

    return [str(item).strip() for item in value if str(item).strip()]


def _normalize_attachments(
    value: str | Path | Sequence[str | Path] | None,
) -> list[str]:
    if value is None:
        return []

    if isinstance(value, (str, Path)):
        items = [value]
    else:
        items = list(value)

    paths: list[str] = []

    for item in items:
        path = Path(item).expanduser().resolve()

        if not path.is_file():
            raise FileNotFoundError(f"Attachment not found: {path}")

        paths.append(str(path))

    return paths


def send_outlook_mail(
    *,
    to: str | Sequence[str],
    subject: str,
    body: str = "",
    cc: str | Sequence[str] | None = None,
    bcc: str | Sequence[str] | None = None,
    attachments: str | Path | Sequence[str | Path] | None = None,
    html_body: str | None = None,
    display_only: bool = False,
    timeout: int = 60,
) -> dict:
    """
    Send or display an Outlook email using the validated Windows Outlook COM path.

    Parameters
    ----------
    to:
        One recipient, a semicolon-separated string, or a sequence of recipients.
    subject:
        Email subject.
    body:
        Plain-text body. Ignored when html_body is provided.
    cc / bcc:
        Optional recipient lists.
    attachments:
        Exact file path(s) generated by the current run.
        Prefer passing the current run's output path instead of scanning for
        "the latest file".
    html_body:
        Optional HTML body.
    display_only:
        True -> open Outlook compose window without sending.
        False -> call Outlook Send().
    timeout:
        Maximum seconds to wait for the PowerShell operation.

    Returns
    -------
    dict
        Result returned by the PowerShell module.

    Raises
    ------
    OutlookMailError
        When Outlook, recipient resolution, attachment, or sending fails.
    """
    to_list = _normalize_addresses(to)
    cc_list = _normalize_addresses(cc)
    bcc_list = _normalize_addresses(bcc)

    if not to_list:
        raise ValueError("At least one TO recipient is required.")

    attachment_list = _normalize_attachments(attachments)

    module_dir = Path(__file__).resolve().parent
    ps_script = module_dir / "outlook_mail.ps1"

    if not ps_script.is_file():
        raise FileNotFoundError(f"PowerShell module not found: {ps_script}")

    config = {
        "to": to_list,
        "cc": cc_list,
        "bcc": bcc_list,
        "subject": str(subject),
        "body": str(body),
        "html_body": html_body or "",
        "attachments": attachment_list,
        "display_only": bool(display_only),
    }

    temp_path: Path | None = None

    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            suffix=".json",
            encoding="utf-8-sig",
            delete=False,
        ) as fp:
            json.dump(config, fp, ensure_ascii=False, indent=2)
            temp_path = Path(fp.name)

        completed = subprocess.run(
            [
                "powershell.exe",
                "-NoProfile",
                "-ExecutionPolicy",
                "Bypass",
                "-File",
                str(ps_script),
                "-ConfigPath",
                str(temp_path),
            ],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
        )

        # PowerShell writes the final result as one JSON line.
        output_lines = [
            line.strip()
            for line in completed.stdout.splitlines()
            if line.strip()
        ]

        if not output_lines:
            stderr = completed.stderr.strip()
            raise OutlookMailError(
                f"No result returned by Outlook module. stderr={stderr!r}"
            )

        try:
            result = json.loads(output_lines[-1])
        except json.JSONDecodeError as exc:
            raise OutlookMailError(
                "Could not parse Outlook module result.\n"
                f"stdout:\n{completed.stdout}\n"
                f"stderr:\n{completed.stderr}"
            ) from exc

        if completed.returncode != 0 or not result.get("ok"):
            raise OutlookMailError(result.get("error", "Outlook send failed."))

        return result

    finally:
        if temp_path is not None:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
